 *
 * Access is gated behind an API key passed in the `Authorization` header as a
 * Bearer token. Two tiers of keys are supported:
 *
 * - Basic keys (`DOCS_REVALIDATION_KEYS`) are subject to a 6-hour rate limit so
 *   that we don't hammer the cache with repeated revalidations.
 * - Override keys (`DOCS_REVALIDATION_OVERRIDE_KEYS`) bypass the rate limit and
 *   can revalidate at any time.
 *
 * Every successful revalidation is logged to Supabase so that the rate limit
 * can be enforced across serverless invocations.
 */

const REVALIDATION_RATE_LIMIT_HOURS = 6
const REVALIDATION_TABLE = 'revalidation_history'
const RECENT_REVALIDATIONS_RPC = 'get_recent_revalidations'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL as string
const supabaseSecretKey = process.env.SUPABASE_SECRET_KEY as string

/**
 * Parse a comma-separated list of API keys from an environment variable into a
 * lookup set, ignoring surrounding whitespace and empty entries.
 */
function parseKeys(value: string | undefined): Set<string> {
  return new Set(
    (value ?? '')
      .split(',')
      .map((key) => key.trim())
      .filter(Boolean)
  )
}

/**
 * Extract the token from an `Authorization: Bearer <token>` header. Returns
 * `null` if the header is missing or not a well-formed Bearer header.
 */
function extractBearerToken(header: string | null): string | null {
  if (!header) return null
  const match = header.match(/^Bearer\s+(.+)$/i)
  return match ? match[1].trim() : null
}

export async function _handleRevalidateRequest(
  request: Request,
  supabase: SupabaseClient = createClient(supabaseUrl, supabaseSecretKey)
): Promise<Response> {
  const authHeader = request.headers.get('authorization')
  if (!authHeader) {
    return new Response('Missing Authorization header', { status: 401 })
  }

  const token = extractBearerToken(authHeader)
  const basicKeys = parseKeys(process.env.DOCS_REVALIDATION_KEYS)
  const overrideKeys = parseKeys(process.env.DOCS_REVALIDATION_OVERRIDE_KEYS)

  const isOverrideKey = token !== null && overrideKeys.has(token)
  const isBasicKey = token !== null && basicKeys.has(token)

  if (!isOverrideKey && !isBasicKey) {
    return new Response('Invalid Authorization header', { status: 401 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    body = undefined
  }

  const tags = (body as { tags?: unknown } | undefined)?.tags
  if (!Array.isArray(tags)) {
    return new Response('Malformed request body', { status: 400 })
  }

  // Basic-tier keys are rate limited: skip revalidation if it already happened
  // within the last 6 hours. Override-tier keys bypass this check entirely.
  if (!isOverrideKey) {
    const cutoff = new Date(
      Date.now() - REVALIDATION_RATE_LIMIT_HOURS * 60 * 60 * 1000
    ).toISOString()

    const { data, error } = await supabase.rpc(RECENT_REVALIDATIONS_RPC, { since: cutoff })
    if (error) {
      return new Response('Error checking revalidation history', { status: 500 })
    }

    const recentlyRevalidated = Array.isArray(data) ? data.length > 0 : Boolean(data)
    if (recentlyRevalidated) {
      return new Response('revalidated within the last 6 hours', { status: 429 })
    }
