  for (const tag of tags) {
    revalidateTag(tag)
  }

  await supabase.from(REVALIDATION_TABLE).insert({ tags })

  return new Response(null, { status: 204 })
}

export async function POST(request: Request) {
  return _handleRevalidateRequest(request)
}
